/// Unified agent names (Task 2): the ambient `CODEX_HOME` fallback for the
/// durability-driven pending bind when the app-server's own initialize
/// result is unavailable (pre-initialize edge). Mirrors
/// `freshell_codex::durability`'s root resolution (CODEX_HOME > `~/.codex`);
/// the initialized `codexHome` captured by the app-server client remains
/// the preferred authority.
fn codex_home_from_env() -> Option<String> {
    if let Ok(v) = std::env::var("CODEX_HOME") {
        if !v.is_empty() {
            return Some(v);
        }
    }
    let home = std::env::var("HOME").ok().filter(|v| !v.is_empty())?;
    Some(format!("{home}/.codex"))
}

/// Unified agent names (Task 2): locate the thread's rollout under
/// `sessions_root` with the SAME ownership proof `freshell-codex`'s rollout
/// locator applies — the filename contains the thread id (a cheap
/// prefilter), and the file's first line is a `session_meta` whose
/// `payload.id`/`payload.session_id` equals the thread (substring matching
/// alone is unsafe: rollouts embed foreign uuids as fork/resume lineage).
/// Bounded recursive walk (`sessions/YYYY/MM/DD/rollout-*.jsonl`, flat in
/// tests). `None` when no rollout is verified — the pending name stays
/// pending (InitialRecovery semantics) until the next turn-completed edge
/// retries (no periodic tick retries a freshcodex bind).
fn locate_thread_rollout(
    sessions_root: &std::path::Path,
    thread_id: &str,
) -> Option<std::path::PathBuf> {
    fn session_meta_owns(path: &std::path::Path, thread_id: &str) -> bool {
        use std::io::{BufRead, Read};
        let Ok(file) = std::fs::File::open(path) else {
            return false;
        };
        let mut first = String::new();
        if std::io::BufReader::new(file)
            .take(1024 * 1024)
            .read_line(&mut first)
            .is_err()
        {
            return false;
        }
        let Ok(value) = serde_json::from_str::<serde_json::Value>(first.trim()) else {
            return false;
        };
        if value.get("type").and_then(serde_json::Value::as_str) != Some("session_meta") {
            return false;
        }
        let Some(payload) = value.get("payload") else {
            return false;
        };
        payload.get("id").and_then(serde_json::Value::as_str) == Some(thread_id)
            || payload
                .get("session_id")
                .and_then(serde_json::Value::as_str)
                == Some(thread_id)
    }
    fn walk(
        dir: &std::path::Path,
        thread_id: &str,
        depth: u8,
        hit: &mut Option<std::path::PathBuf>,
    ) {
        if depth > 5 || hit.is_some() {
            return;
        }
        let Ok(entries) = std::fs::read_dir(dir) else {
            return;
        };
        for entry in entries.flatten() {
            if hit.is_some() {
                return;
            }
            let path = entry.path();
            if path.is_dir() {
                walk(&path, thread_id, depth + 1, hit);
            } else if path
                .file_name()
                .and_then(|n| n.to_str())
                .is_some_and(|n| n.ends_with(".jsonl") && n.contains(thread_id))
                && session_meta_owns(&path, thread_id)
            {
                *hit = Some(path);
            }
        }
    }
    if thread_id.is_empty()
        || thread_id.contains('/')
        || thread_id.contains('\\')
        || thread_id.contains("..")
    {
        return None;
    }
    let mut hit = None;
    walk(sessions_root, thread_id, 0, &mut hit);
    hit
}

pub(crate) fn read_large_native_display(
    codex_home: &std::path::Path,
    thread_id: &str,
) -> Result<Option<Value>, String> {
    let Some(path) = locate_thread_rollout(&codex_home.join("sessions"), thread_id) else {
        return Err("selected Codex rollout is unavailable".into());
    };
    if std::fs::metadata(&path)
        .map_err(|error| error.to_string())?
        .len()
        <= crate::native_history::RETAINED_TURN_BYTES as u64
    {
        return Ok(None);
    }
    native_history::read_rollout(&path, thread_id).map(Some)
}

fn join_retained_codex_display(snapshot: &mut Value, mut saved: Value) {
    let live = snapshot["turns"]
        .as_array_mut()
        .map(std::mem::take)
        .unwrap_or_default();
    let live_roots = live
        .iter()
        .filter_map(|turn| turn["turnId"].as_str())
        .map(|id| {
            id.rsplit_once(":row-")
                .filter(|(_, index)| index.parse::<usize>().is_ok())
                .map_or(id, |(id, _)| id)
                .to_owned()
        })
        .collect::<std::collections::HashSet<_>>();
    let mut turns = saved["turns"]
        .as_array_mut()
        .map(std::mem::take)
        .unwrap_or_default();
    let replacement_ordinal = turns
        .iter()
        .filter(|turn| {
            let id = turn["turnId"].as_str().unwrap_or("");
            live_roots.iter().any(|root| {
                id == root
                    || id
                        .strip_prefix(root)
                        .is_some_and(|suffix| suffix.starts_with(":row-"))
            })
        })
        .filter_map(|turn| turn["ordinal"].as_u64())
        .min();
    turns.retain(|turn| {
        let id = turn["turnId"].as_str().unwrap_or("");
        !live_roots.iter().any(|root| {
            id == root
                || id
                    .strip_prefix(root)
                    .is_some_and(|suffix| suffix.starts_with(":row-"))
        })
    });
    let ordinal = replacement_ordinal.unwrap_or_else(|| {
        turns
            .iter()
            .filter_map(|turn| turn["ordinal"].as_u64())
            .max()
            .map_or(0, |value| value + 1)
    });
    turns.extend(live.into_iter().enumerate().map(|(index, mut turn)| {
        turn["ordinal"] = json!(ordinal + index as u64);
        turn
    }));
    let (diffs, children) = metadata::transcript_metadata(&turns);
    snapshot["capabilities"]["diffs"] = json!(!diffs.is_empty());
    snapshot["capabilities"]["childThreads"] = json!(!children.is_empty());
    snapshot["diffs"] = json!(diffs);
    snapshot["childThreads"] = json!(children);
    snapshot["turns"] = json!(turns);
    for key in ["nativeHistoryRetention", "nativeHistoryActivity"] {
        if let Some(value) = saved["extensions"]["codex"].get(key) {
            snapshot["extensions"]["codex"][key] = value.clone();
        }
    }
    crate::native_history::retain_snapshot_display("codex", snapshot);
}

/// The codex fresh-agent `sessionType` (`AGENT_SESSION_TYPES.codex`).
const SESSION_TYPE: &str = "freshcodex";

fn classify_codex_startup_stderr(stderr: &[u8]) -> &'static str {
    if stderr.is_empty() {
        return "no-diagnostic";
    }
    let lower = String::from_utf8_lossy(stderr).to_ascii_lowercase();
    if [
        "not logged in",
        "login required",
        "codex login",
        "authentication",
        "credentials",
        "unauthorized",
        "token expired",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        "authentication"
    } else if [
        "unknown option",
        "unrecognized option",
        "unknown argument",
        "unexpected argument",
        "usage:",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        "arguments"
    } else if [
        "address already in use",
        "failed to bind",
        "bind failed",
        "permission denied",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        "listener"
    } else if [
        "config.toml",
        "invalid config",
        "configuration error",
        "failed to parse config",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        "configuration"
    } else if [
        "connection refused",
        "could not resolve",
        "dns",
        "network error",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        "network"
    } else {
        "unclassified"
    }
}
