    pub(super) fn state_with_bus() -> (FreshCodexState, tokio::sync::broadcast::Receiver<String>) {
        let (tx, rx) = tokio::sync::broadcast::channel::<String>(64);
        let st = FreshCodexState::new(
            Arc::new("tok".to_string()),
            Arc::new(tx),
            json!({ "freshAgent": { "enabled": false } }),
        );
        (st, rx)
    }

    /// `state_with_bus` + a wired in-memory identity sink (kata 1wxv Tasks 2-4):
    /// the rollback handlers AWAIT durable rollback-record writes BEFORE any
    /// provider mutation, so their tests need the fake ledger surface
    /// (`record_rollback`/`load_rollback`, `set_fail_writes`).
    pub(super) fn state_with_sink() -> (
        FreshCodexState,
        tokio::sync::broadcast::Receiver<String>,
        std::sync::Arc<crate::identity_sink::FakeIdentitySink>,
    ) {
        let (st, rx) = state_with_bus();
        let fake = std::sync::Arc::new(crate::identity_sink::FakeIdentitySink::default());
        st.set_identity_sink(fake.clone());
        (st, rx, fake)
    }

    type SessionRegistrationPauseChannels = (
        oneshot::Receiver<(String, Option<u32>, String)>,
        oneshot::Sender<()>,
    );

    struct RegistrationCleanupCheck<'a> {
        state: &'a FreshCodexState,
        registry: &'a freshell_ownership::RuntimeOwnershipRegistry,
        id: &'a str,
        operation_id: &'a str,
        generation: u64,
        pid: u32,
        runtime_id: &'a str,
        cleanup_entered_rx: &'a mut tokio::sync::mpsc::UnboundedReceiver<
            crate::session_lease::CondemnedRuntimeIdentity,
        >,
        cleanup_completed_rx: &'a mut tokio::sync::mpsc::UnboundedReceiver<bool>,
        cleanup_release_tx: &'a tokio::sync::watch::Sender<bool>,
    }

    fn arm_session_registration_pause(state: &FreshCodexState) -> SessionRegistrationPauseChannels {
        let (registration_tx, registration_rx) =
            oneshot::channel::<(String, Option<u32>, String)>();
        let registration_tx = Arc::new(StdMutex::new(Some(registration_tx)));
        let (release_tx, release_rx) = oneshot::channel::<()>();
        let release_rx = Arc::new(StdMutex::new(Some(release_rx)));
        state.set_session_registration_pause_for_tests(Arc::new(
            move |thread_id, sidecar_pid, sidecar_ownership_id| {
                let registration = registration_tx
                    .lock()
                    .expect("registration sender lock")
                    .take();
                let release = release_rx.lock().expect("registration release lock").take();
                Box::pin(async move {
                    if let Some(registration) = registration {
                        let _ = registration.send((thread_id, sidecar_pid, sidecar_ownership_id));
                    }
                    if let Some(release) = release {
                        let _ = release.await;
                    }
                })
            },
        ));
        (registration_rx, release_tx)
    }

    fn arm_delayed_exact_cleanup(
        state: &FreshCodexState,
    ) -> (
        tokio::sync::mpsc::UnboundedReceiver<crate::session_lease::CondemnedRuntimeIdentity>,
        tokio::sync::mpsc::UnboundedReceiver<bool>,
        tokio::sync::watch::Sender<bool>,
    ) {
        let (entered_tx, entered_rx) = tokio::sync::mpsc::unbounded_channel();
        let (completed_tx, completed_rx) = tokio::sync::mpsc::unbounded_channel();
        let (release_tx, release_rx) = tokio::sync::watch::channel(false);
        state.set_sidecar_cleanup_probe(Arc::new(move |recorded| {
            let entered = entered_tx.clone();
            let completed = completed_tx.clone();
            let mut release = release_rx.clone();
            Box::pin(async move {
                let _ = entered.send(recorded.clone());
                while !*release.borrow() {
                    if release.changed().await.is_err() {
                        return Ok(false);
                    }
                }
                let confirmed = crate::session_lease::kill_and_confirm_recorded_tree_dead(
                    &recorded,
                    CODEX_SIDECAR_OWNERSHIP_ENV,
                )
                .await;
                let _ = completed.send(confirmed);
                Ok(confirmed)
            })
        }));
        (entered_rx, completed_rx, release_tx)
    }

    async fn cancel_registration_and_confirm_cleanup<T: Send + 'static>(
        task: tokio::task::JoinHandle<T>,
        sessions: tokio::sync::MutexGuard<'_, HashMap<String, CodexSession>>,
        check: RegistrationCleanupCheck<'_>,
    ) -> (bool, bool) {
        task.abort();
        assert!(matches!(task.await, Err(error) if error.is_cancelled()));

        let owner_retained = matches!(
            check.registry.observe(PROVIDER, check.id).state,
            freshell_ownership::OwnershipState::Starting {
                kind: freshell_ownership::RuntimeOwnerKind::FreshAgent,
                operation_id: current_operation,
                generation: current_generation,
                ..
            } if current_operation == check.operation_id && current_generation == check.generation
        );
        let competitor = check.registry.begin_start(
            PROVIDER,
            check.id,
            freshell_ownership::RuntimeOwnerKind::Terminal,
            "terminal-during-codex-registration-cleanup",
            None,
            "codex-registration-cancellation-test",
            crate::session_lease::now_epoch_ms(),
        );
        let terminal_refused = matches!(
            &competitor,
            freshell_ownership::BeginOutcome::Blocked {
                state: freshell_ownership::OwnershipState::Starting {
                    operation_id: current_operation,
                    generation: current_generation,
                    ..
                },
                ..
            } if current_operation == check.operation_id && *current_generation == check.generation
        );
        if let freshell_ownership::BeginOutcome::Granted {
            generation: competing_generation,
        } = competitor
        {
            let _ = check.registry.fail(
                PROVIDER,
                check.id,
                "terminal-during-codex-registration-cleanup",
                competing_generation,
                false,
            );
        }
        drop(sessions);

        let recorded =
            match tokio::time::timeout(Duration::from_secs(10), check.cleanup_entered_rx.recv())
                .await
            {
                Ok(Some(recorded)) => recorded,
                _ => {
                    let recorded = crate::session_lease::record_condemned_runtime_identity(
                        check.pid,
                        CODEX_SIDECAR_OWNERSHIP_ENV,
                        check.runtime_id,
                    );
                    assert!(
                        crate::session_lease::kill_and_confirm_recorded_tree_dead(
                            &recorded,
                            CODEX_SIDECAR_OWNERSHIP_ENV,
                        )
                        .await
                    );
                    panic!("cancellation did not transfer cleanup to the exact-writer probe");
                }
            };
        assert_eq!(recorded.pid, check.pid);
        assert_eq!(recorded.ownership_id, check.runtime_id);
        check.cleanup_release_tx.send(true).unwrap();
        assert!(
            tokio::time::timeout(Duration::from_secs(10), check.cleanup_completed_rx.recv(),)
                .await
                .expect("cleanup confirmation settles")
                .expect("cleanup reports its confirmation"),
            "the exact native writer must be confirmed dead"
        );
        tokio::time::timeout(Duration::from_secs(10), async {
            while !matches!(
                check.registry.observe(PROVIDER, check.id).state,
                freshell_ownership::OwnershipState::Vacant
            ) {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("confirmed cleanup and durable repair release the startup claim");
        check.state.shutdown().await;
        (owner_retained, terminal_refused)
    }

    struct SharedRecoveryCancellationCheck<'a> {
        state: &'a FreshCodexState,
        registry: &'a freshell_ownership::RuntimeOwnershipRegistry,
        attach_id: &'a str,
        owner_id: &'a str,
        operation_id: &'a str,
        generation: u64,
        pid: u32,
        runtime_id: &'a str,
    }

    async fn cancel_recovery_waiter_and_confirm_shared_launch<T: Send + 'static>(
        task: tokio::task::JoinHandle<T>,
        sessions: tokio::sync::MutexGuard<'_, HashMap<String, CodexSession>>,
        check: SharedRecoveryCancellationCheck<'_>,
    ) -> (bool, bool) {
        task.abort();
        assert!(matches!(task.await, Err(error) if error.is_cancelled()));

        let owner_retained = matches!(
            check.registry.observe(PROVIDER, check.owner_id).state,
            freshell_ownership::OwnershipState::Starting {
                kind: freshell_ownership::RuntimeOwnerKind::FreshAgent,
                operation_id: current_operation,
                generation: current_generation,
                ..
            } if current_operation == check.operation_id && current_generation == check.generation
        );
        let competitor = check.registry.begin_start(
            PROVIDER,
            check.owner_id,
            freshell_ownership::RuntimeOwnerKind::Terminal,
            "terminal-during-shared-codex-recovery",
            None,
            "codex-shared-recovery-cancellation-test",
            crate::session_lease::now_epoch_ms(),
        );
        let terminal_refused = matches!(
            &competitor,
            freshell_ownership::BeginOutcome::Blocked {
                state: freshell_ownership::OwnershipState::Starting {
                    operation_id: current_operation,
                    generation: current_generation,
                    ..
                },
                ..
            } if current_operation == check.operation_id && *current_generation == check.generation
        );
        if let freshell_ownership::BeginOutcome::Granted {
            generation: competing_generation,
        } = competitor
        {
            let _ = check.registry.fail(
                PROVIDER,
                check.owner_id,
                "terminal-during-shared-codex-recovery",
                competing_generation,
                false,
            );
        }

        // The first request only owned a waiter. Its shared provider operation
        // remains parked at session registration and keeps the Starting fence.
        // A second view may join while that same operation owns the fence.
        let second_state = check.state.clone();
        let attach_id = check.attach_id.to_string();
        let second_view = tokio::spawn(async move {
            second_state
                .handle_attach_events(attach_msg(&attach_id))
                .await;
        });
        drop(sessions);
        tokio::time::timeout(Duration::from_secs(20), second_view)
            .await
            .expect("the surviving view joins and receives the shared recovery")
            .expect("the joined attach handler settles");
        tokio::time::timeout(Duration::from_secs(10), async {
            while !check.state.has_live_session(check.owner_id).await {
                tokio::time::sleep(Duration::from_millis(5)).await;
            }
        })
        .await
        .expect("the detached provider operation commits its runtime");
        let sessions = check.state.sessions.lock().await;
        let live_session = sessions
            .get(check.owner_id)
            .expect("the shared provider operation registers its canonical session");
        assert_eq!(live_session.sidecar_pid, Some(check.pid));
        assert_eq!(live_session.sidecar_ownership_id, check.runtime_id);
        let owner_committed = matches!(
            check.registry.observe(PROVIDER, check.owner_id).state,
            freshell_ownership::OwnershipState::Live {
                owner: freshell_ownership::OwnerIdentity {
                    kind: freshell_ownership::RuntimeOwnerKind::FreshAgent,
                    live_session_key: Some(owner_session_key),
                    pid: Some(owner_pid),
                    ownership_id: Some(owner_operation),
                    ..
                },
                ..
            } if owner_session_key == check.owner_id
                && owner_pid == check.pid
                && owner_operation == check.operation_id
        );
        assert!(
            owner_committed,
            "the shared operation keeps its exact native writer"
        );
        assert_eq!(
            check
                .state
                .session_recovery
                .status(&format!("codex:{}", check.owner_id))
                .await,
            None
        );
        (owner_retained, terminal_refused)
    }

    /// Insert a `CodexSession` directly (bypassing the real sidecar spawn `handle_create`
    /// requires) so `handle_interrupt`/`handle_kill` can be exercised against a scripted
    /// [`freshell_codex::ChannelPeer`] / a real-but-harmless child process.
    async fn insert_fake_session(
        state: &FreshCodexState,
        thread_id: &str,
        client: Arc<CodexAppServerClient>,
        active_turn: Arc<StdMutex<Option<String>>>,
        child: tokio::process::Child,
        ownership_id: &str,
    ) -> tokio::sync::broadcast::Receiver<String> {
        // no-op consumer: these tests drive the reducer/RPC surfaces directly.
        let turn_state = Arc::new(StdMutex::new(CodexTurnState::default()));
        let consumer = tokio::spawn(async {});
        let (kill_tx, kill_rx) = oneshot::channel();
        let exited = Arc::new(AtomicBool::new(false));
        let quiet_deadman = QuietDeadman::new_shared();
        // The fixture's in-flight truth mirrors its `active_turn` seed: a
        // session inserted mid-turn is in flight for the crash edge too (the
        // production latch invariant — every `active_turn` set has its latch
        // mirror).
        let turn_in_flight = Arc::new(AtomicBool::new(
            active_turn.lock().expect("active_turn mutex").is_some(),
        ));
        // FR1-1: the retired-turn slot (starts empty like production).
        let retired_turn_id: Arc<StdMutex<Option<String>>> = Arc::new(StdMutex::new(None));
        // (E3R1: no already-rang set here — this fixture's consumer is a
        // no-op, so the set has no reader.)
        let last_turn_complete_at: Arc<StdMutex<Option<i64>>> = Arc::new(StdMutex::new(None));
        let sidecar_pid = child.id();
        let sidecar_ownership_id = ownership_id.to_string();
        let (watcher, sidecar_identity) = spawn_exit_watcher_tracking_turns(
            child,
            ownership_id.to_string(),
            thread_id.to_string(),
            state.broadcast_tx.clone(),
            kill_rx,
            exited.clone(),
            Arc::clone(&state.leases),
            quiet_deadman.clone(),
            turn_in_flight.clone(),
            retired_turn_id.clone(),
            last_turn_complete_at.clone(),
            Arc::clone(&state.condemned_priors),
            None,
            Some(turn_state.clone()),
            Some(state.clone()),
            None,
            None,
            None,
        );
        state.sessions.lock().await.insert(
            thread_id.to_string(),
            CodexSession {
                collaboration_mode: None,
                native_turn_settings: None,
                native_thread_settings: None,
                turn_state: turn_state.clone(),
                client,
                model: "gpt-5.3-codex-spark".to_string(),
                effort: None,
                cwd: None,
                sandbox: None,
                permission_mode: None,
                active_turn,
                user_interrupt_pending: Arc::new(AtomicBool::new(false)),
                compact_in_flight: Arc::new(AtomicBool::new(false)),
                compact_turn_id: Arc::new(StdMutex::new(None)),
                // These fixtures model threads freshell started (paginated).
                history_mode: Some(HistoryMode::Paginated),
                turn_lock: Arc::new(TokioMutex::new(())),
                event_emission_gate: Arc::new(TokioMutex::new(())),
                projection: Arc::new(StdMutex::new(projection::CodexProjection::new(
                    mint_ownership_id(),
                    thread_id.to_string(),
                ))),
                notification_drain: None,
                consumer,
                kill_tx: Some(kill_tx),
                handoff_tx: None,
                watcher,
                exited,
                checkpoint_probe_cancelled: Arc::new(AtomicBool::new(false)),
                sidecar_pid,
                sidecar_identity,
                sidecar_ownership_id,
                quiet_deadman,
                turn_in_flight,
                retired_turn_id,
                last_turn_complete_at,
                provenance: None,
            },
        );
        state.broadcast_tx.subscribe()
    }

    /// A harmless real child that stays alive until reaped (the interrupt/kill tests' fake
    /// "owned sidecar" -- no real `codex` binary needed).
    pub(super) fn spawn_sleeper() -> tokio::process::Child {
        let mut cmd = tokio::process::Command::new("sleep");
        cmd.arg("30");
        cmd.kill_on_drop(true);
        cmd.spawn().expect("spawn sleep fixture")
    }

    pub(super) fn spawn_sleeper_with_owner(ownership_id: &str) -> tokio::process::Child {
        let mut cmd = tokio::process::Command::new("sleep");
        cmd.arg("30")
            .env(CODEX_SIDECAR_OWNERSHIP_ENV, ownership_id)
            .kill_on_drop(true);
        cmd.spawn().expect("spawn owned sleep fixture")
    }

    /// Like [`insert_fake_session`], but wires the REAL notification-consumer
    /// ([`FreshCodexState::spawn_consumer`]) instead of a no-op, so a scripted
    /// `turn/completed` notification pushed via the paired
    /// [`freshell_codex::ChannelPeer`] actually flows through [`reduce_notification`]
    /// and clears `active_turn` -- exercising the exact production path `get_snapshot`
    /// (REST) relies on for `capabilities.send`.
    pub(super) async fn insert_fake_session_with_real_consumer(
        state: &FreshCodexState,
        thread_id: &str,
        client: Arc<CodexAppServerClient>,
        active_turn: Arc<StdMutex<Option<String>>>,
        notifs: tokio::sync::mpsc::UnboundedReceiver<CodexNotification>,
        child: tokio::process::Child,
        ownership_id: &str,
    ) -> tokio::sync::broadcast::Receiver<String> {
        insert_fake_session_with_real_consumer_after_gate(
            state,
            thread_id,
            client,
            active_turn,
            notifs,
            child,
            ownership_id,
            None,
        )
        .await
    }

    #[allow(clippy::too_many_arguments)]
    async fn insert_fake_session_with_real_consumer_after_gate(
        state: &FreshCodexState,
        thread_id: &str,
        client: Arc<CodexAppServerClient>,
        active_turn: Arc<StdMutex<Option<String>>>,
        notifs: tokio::sync::mpsc::UnboundedReceiver<CodexNotification>,
        child: tokio::process::Child,
        ownership_id: &str,
        before_insert: Option<(oneshot::Sender<()>, oneshot::Receiver<()>)>,
    ) -> tokio::sync::broadcast::Receiver<String> {
        let quiet_deadman = QuietDeadman::new_shared();
        let user_interrupt_pending: Arc<AtomicBool> = Arc::new(AtomicBool::new(false));
        // The fixture's in-flight truth mirrors its `active_turn` seed (the
        // production latch invariant).
        let turn_in_flight = Arc::new(AtomicBool::new(
            active_turn.lock().expect("active_turn mutex").is_some(),
        ));
        // FR1-1: the retired-turn slot (starts empty like production).
        let retired_turn_id: Arc<StdMutex<Option<String>>> = Arc::new(StdMutex::new(None));
        // DR5-2 → E3R1: the durable already-rang set (starts empty like
        // production).
        let status_rang_turn_ids: Arc<StdMutex<Vec<String>>> = Arc::new(StdMutex::new(Vec::new()));
        let last_turn_complete_at: Arc<StdMutex<Option<i64>>> = Arc::new(StdMutex::new(None));
        let compact_in_flight = Arc::new(AtomicBool::new(false));
        let compact_turn_id = Arc::new(StdMutex::new(None));
        let event_emission_gate = Arc::new(TokioMutex::new(()));
        let turn_state = Arc::new(StdMutex::new(CodexTurnState::default()));
        let projection = Arc::new(StdMutex::new(projection::CodexProjection::new(
            mint_ownership_id(),
            thread_id.to_string(),
        )));
        let (notification_drain, drain_completed) = CodexNotificationDrain::new();
        let (registered_tx, registered_rx) = oneshot::channel();
        let consumer = state.spawn_consumer(
            notifs,
            CodexConsumerRuntime {
                turn_state: turn_state.clone(),
                thread_id: thread_id.to_string(),
                active_turn: active_turn.clone(),
                user_interrupt_pending: user_interrupt_pending.clone(),
                quiet_deadman: quiet_deadman.clone(),
                turn_in_flight: turn_in_flight.clone(),
                retired_turn_id: retired_turn_id.clone(),
                status_rang_turn_ids: status_rang_turn_ids.clone(),
                last_turn_complete_at: last_turn_complete_at.clone(),
                compact_in_flight: compact_in_flight.clone(),
                compact_turn_id: compact_turn_id.clone(),
                event_emission_gate: event_emission_gate.clone(),
                projection: projection.clone(),
                drain_completed,
            },
        );
        let (kill_tx, kill_rx) = oneshot::channel();
        let (handoff_tx, handoff_rx) = oneshot::channel();
        let exited = Arc::new(AtomicBool::new(false));
        let sidecar_pid = child.id();
        let sidecar_ownership_id = ownership_id.to_string();
        let (watcher, sidecar_identity) = spawn_exit_watcher_tracking_turns(
            child,
            ownership_id.to_string(),
            thread_id.to_string(),
            state.broadcast_tx.clone(),
            kill_rx,
            exited.clone(),
            Arc::clone(&state.leases),
            quiet_deadman.clone(),
            turn_in_flight.clone(),
            retired_turn_id.clone(),
            last_turn_complete_at.clone(),
            Arc::clone(&state.condemned_priors),
            None,
            Some(turn_state.clone()),
            Some(state.clone()),
            Some(notification_drain.clone()),
            Some(registered_rx),
            Some(handoff_rx),
        );
        if let Some((ready, proceed)) = before_insert {
            // Give an immediate exit enough time to finish on the old code;
            // the fixed watcher waits here for registration instead.
            let _ = tokio::time::timeout(Duration::from_millis(500), async {
                while !watcher.is_finished() {
                    tokio::time::sleep(Duration::from_millis(1)).await;
                }
            })
            .await;
            let _ = ready.send(());
            let _ = proceed.await;
        }
        state.sessions.lock().await.insert(
            thread_id.to_string(),
            CodexSession {
                collaboration_mode: None,
                native_turn_settings: None,
                native_thread_settings: None,
                turn_state: turn_state.clone(),
                client,
                model: "gpt-5.3-codex-spark".to_string(),
                effort: None,
                cwd: None,
                sandbox: None,
                permission_mode: None,
                active_turn,
                user_interrupt_pending,
                compact_in_flight,
                compact_turn_id,
                // These fixtures model threads freshell started (paginated).
                history_mode: Some(HistoryMode::Paginated),
                turn_lock: Arc::new(TokioMutex::new(())),
                event_emission_gate,
                projection,
                notification_drain: Some(notification_drain),
                consumer,
                kill_tx: Some(kill_tx),
                handoff_tx: Some(handoff_tx),
                watcher,
                exited,
                checkpoint_probe_cancelled: Arc::new(AtomicBool::new(false)),
                sidecar_pid,
                sidecar_identity,
                sidecar_ownership_id,
                quiet_deadman,
                turn_in_flight,
                retired_turn_id,
                last_turn_complete_at,
                provenance: None,
            },
        );
        let _ = registered_tx.send(());
        state.broadcast_tx.subscribe()
    }

    /// FIX-1 (codex-first triage): after a turn genuinely completes through the REAL
    /// notification-consumer path (not a hand-set mutex), a subsequent `get_snapshot`
    /// must report `capabilities.send: true` -- matching the legacy adapter
    /// (`normalizeCodexThreadSnapshot`, `normalize.ts:756,765`), which computes
    /// `send`/`interrupt`/`fork` PURELY from the freshly-read thread status, never
    /// from an independently-tracked in-flight-turn bit. Reproduces the E2E-observed
    /// regression documented in `test/e2e-browser/specs/restore-matrix.spec.ts`'s
    /// `test.fail` comment: the FreshCodex composer stays permanently disabled after
    /// the first live turn completes.
    #[tokio::test]
    async fn get_snapshot_reports_sendable_after_a_turn_completes_via_the_real_notification_stream()
    {
        let native_home = small_native_home("thread-1");
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, notifs) = CodexAppServerClient::connect(transport);
        let client = Arc::new(client);

        let (st, mut rx) = state_with_bus();
        let active_turn = Arc::new(StdMutex::new(Some("turn-1".to_string())));
        insert_fake_session_with_real_consumer(
            &st,
            "thread-1",
            client,
            active_turn.clone(),
            notifs,
            spawn_sleeper(),
            "codex-sidecar-test-turn-complete-capabilities",
        )
        .await;

        // The real app-server pushes `turn/completed` for the tracked thread -- exactly
        // what `handle_send`'s consumer (`spawn_consumer` -> `reduce_notification`)
        // observes in production.
        peer.emit_notification(
            "turn/completed",
            json!({ "threadId": "thread-1", "turnId": "turn-1", "status": "completed" }),
        );

        // The newly observed turn first initializes and settles its retained
        // projection. Its lifecycle snapshot still follows both frames.
        let init: Value = serde_json::from_str(&rx.recv().await.unwrap()).unwrap();
        assert_eq!(init["event"]["type"], "freshAgent.session.init");
        let patch: Value = serde_json::from_str(&rx.recv().await.unwrap()).unwrap();
        assert_eq!(patch["event"]["type"], "freshAgent.transcript.patch");
        assert!(patch["event"]["ops"].as_array().unwrap().iter().any(|op| {
            op["op"] == "settleTurn"
                && op["nativeTurnId"] == "turn-1"
                && op["status"] == "completed"
        }));

        // Deterministic sync: the consumer clears `active_turn` BEFORE its
        // lifecycle snapshot, so this wait proves the clear has happened.
        let frame = rx.recv().await.expect("idle snapshot frame");
        let wire: Value = serde_json::from_str(&frame).unwrap();
        assert_eq!(wire["event"]["type"], "freshAgent.session.snapshot");

        assert!(
            active_turn.lock().expect("active_turn mutex").is_none(),
            "active_turn must be cleared by the real notification consumer"
        );

        let driver = {
            let st = st.clone();
            tokio::spawn(async move { st.get_snapshot("thread-1", None).await })
        };

        let (init_id, init_method, _p) = peer.expect_request().await;
        assert_eq!(init_method, "initialize");
        peer.respond(
            &init_id,
            json!({ "userAgent": "x", "codexHome": native_home.path(), "platformFamily": "u", "platformOs": "l" }),
        );
        let _ = peer.expect_notification().await;

        let (id, method, _params) = peer.expect_request().await;
        assert_eq!(method, "thread/read");
        peer.respond(
            &id,
            json!({
                "thread": {
                    "id": "thread-1",
                    "status": { "type": "idle" },
                    "turns": [],
                }
            }),
        );

        let snapshot = driver.await.unwrap().expect("snapshot builds");
        assert_eq!(snapshot["status"], json!("idle"));
        assert_eq!(
            snapshot["capabilities"]["send"],
            json!(true),
            "composer must be sendable once the real notification stream has cleared the active turn"
        );
        assert_eq!(snapshot["capabilities"]["interrupt"], json!(false));
    }

    // ── unified agent names (Task 3 fix round, M6): the consumer's
    // ThreadNameUpdated fold resolves through the runtime thread-id→pending
    // association like the CLI lanes, so an external rename observed BEFORE
    // the durable rollout bind folds instead of NotFound-dropping.

    /// A naming sink that records every native observation (its chosen target
    /// and whether that target resolved) — the freshagent-side pin for the
    /// consumer's fold resolution. The real store's own acceptance policy is
    /// pinned in `freshell-server`'s suites.
    struct ObservationRecordingSink {
        observations: StdMutex<Vec<(freshell_protocol::session_names::SessionNameRef, bool)>>,
        records: StdMutex<
            std::collections::HashMap<String, freshell_protocol::session_names::SessionNameRecord>,
        >,
    }

    impl ObservationRecordingSink {
        fn new() -> std::sync::Arc<Self> {
            std::sync::Arc::new(Self {
                observations: StdMutex::new(Vec::new()),
                records: StdMutex::new(std::collections::HashMap::new()),
            })
        }

        fn key_of(target: &freshell_protocol::session_names::SessionNameRef) -> String {
            serde_json::to_string(target).expect("ref serializes")
        }

        fn update_for(
            &self,
            record: freshell_protocol::session_names::SessionNameRecord,
        ) -> freshell_protocol::session_names::SessionNameUpdate {
            freshell_protocol::session_names::SessionNameUpdate {
                redirects: Vec::new(),
                record,
                document_generation: 1,
                changed: false,
                native_sync: None,
                outcome: None,
            }
        }
    }

    impl crate::naming::SessionNaming for ObservationRecordingSink {
        fn get(
            &self,
            refs: Vec<freshell_protocol::session_names::SessionNameRef>,
        ) -> crate::naming::NameFuture<Vec<freshell_protocol::session_names::SessionNameUpdate>>
        {
            let updates = refs
                .into_iter()
                .filter_map(|target| {
                    self.records
                        .lock()
                        .unwrap()
                        .get(&Self::key_of(&target))
                        .cloned()
                })
                .map(|record| self.update_for(record))
                .collect();
            Box::pin(async move { Ok(updates) })
        }

        fn ensure_pending(
            &self,
            input: crate::naming::PendingNameInput,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            let target = freshell_protocol::session_names::SessionNameRef::Pending {
                id: input.handle.clone(),
            };
            if let Some(existing) = self
                .records
                .lock()
                .unwrap()
                .get(&Self::key_of(&target))
                .cloned()
            {
                let update = self.update_for(existing);
                return Box::pin(async move { Ok(update) });
            }
            let record = freshell_protocol::session_names::SessionNameRecord {
                name_ref: target.clone(),
                name: "proj".to_string(),
                source: freshell_protocol::session_names::NameSource::Directory,
                revision: 1,
                manual_revision: None,
                renamed_at: None,
                legacy_origin: None,
            };
            let update = self.update_for(record.clone());
            self.records
                .lock()
                .unwrap()
                .insert(Self::key_of(&target), record);
            Box::pin(async move { Ok(update) })
        }

        fn bind_pending(
            &self,
            _input: crate::naming::BindNameInput,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            Box::pin(async move {
                Err(crate::naming::NameError::NotFound(
                    "not needed here".to_string(),
                ))
            })
        }

        fn rename(
            &self,
            _input: crate::naming::RenameNameInput,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            Box::pin(async move {
                Err(crate::naming::NameError::NotFound(
                    "not needed here".to_string(),
                ))
            })
        }

        fn activity(
            &self,
            _input: crate::naming::NameActivity,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            Box::pin(async move {
                Err(crate::naming::NameError::NotFound(
                    "not needed here".to_string(),
                ))
            })
        }

        fn observe_native(
            &self,
            input: crate::naming::NativeNameObservation,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            let record = self
                .records
                .lock()
                .unwrap()
                .get(&Self::key_of(&input.target))
                .cloned();
            self.observations
                .lock()
                .unwrap()
                .push((input.target.clone(), record.is_some()));
            let answer = match record {
                Some(record) => Ok(self.update_for(record)),
                None => Err(crate::naming::NameError::NotFound(format!(
                    "no naming record for {}",
                    Self::key_of(&input.target)
                ))),
            };
            Box::pin(async move { answer })
        }

        fn record_acquisition(
            &self,
            target: freshell_protocol::session_names::SessionNameRef,
            _acquisition: freshell_protocol::native_location::NativeAcquisition,
        ) -> crate::naming::NameFuture<freshell_protocol::session_names::SessionNameUpdate>
        {
            let answer = Err(crate::naming::NameError::NotFound(format!(
                "no record for {}",
                Self::key_of(&target)
            )));
            Box::pin(async move { answer })
        }
    }

    /// M6 (Task 3 fix round): the fresh-codex consumer's `ThreadNameUpdated`
    /// fold resolves through the runtime thread-id→pending association (the
    /// CLI lanes' `named_session_ref_of(...).or(name_ref_for(...))` shape) —
    /// an external rename observed BEFORE the durable rollout bind folds onto
    /// the stashed pending record instead of NotFound-dropping.
    #[tokio::test]
    async fn an_external_rename_before_the_durable_bind_folds_via_the_pending_handle() {
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, notifs) = CodexAppServerClient::connect(transport);
        let client = Arc::new(client);

        let (st, _rx) = state_with_bus();
        let sink = ObservationRecordingSink::new();
        st.set_session_naming(sink.clone());
        // A pre-durable pending record plus the runtime thread→handle stash
        // (exactly what a freshcodex create carries before its rollout lands).
        use crate::naming::SessionNaming as _;
        sink.ensure_pending(crate::naming::PendingNameInput {
            handle: "handle-pending-rename".to_string(),
            provider: freshell_protocol::session_names::NamedProvider::Codex,
            cwd: Some("/w/proj".to_string()),
        })
        .await
        .expect("ensure pending");
        st.naming_handles.lock().await.insert(
            "thread-pending-rename".to_string(),
            "handle-pending-rename".to_string(),
        );
        let active_turn = Arc::new(StdMutex::new(None));
        insert_fake_session_with_real_consumer(
            &st,
            "thread-pending-rename",
            client,
            active_turn,
            notifs,
            spawn_sleeper(),
            "codex-sidecar-test-name-updated-pending",
        )
        .await;

        // The upstream renames the thread BEFORE the rollout bind verifies.
        peer.emit_notification(
            "thread/name/updated",
            json!({ "threadId": "thread-pending-rename", "name": "Externally Renamed" }),
        );

        let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(2);
        loop {
            if sink.observations.lock().unwrap().len() == 1 {
                break;
            }
            assert!(
                tokio::time::Instant::now() < deadline,
                "the consumer never folded the thread/name/updated notification"
            );
            tokio::time::sleep(std::time::Duration::from_millis(10)).await;
        }
        let (target, folded) = sink.observations.lock().unwrap()[0].clone();
        assert!(
            matches!(
                &target,
                freshell_protocol::session_names::SessionNameRef::Pending { id }
                    if id == "handle-pending-rename"
            ),
            "the pre-bind observation resolves through the thread→pending association, got {target:?}"
        );
        assert!(
            folded,
            "the observation folds (the pending record resolves) instead of NotFound-dropping"
        );
    }

    /// Unified agent names (Task 8 acceptance): the pre-durable pending
    /// record is admitted at REQUEST RECEIPT, not after the app-server
    /// answers `thread/start`. The pane content (and the client's rename
    /// capture) carries the handle from the moment the create frame is
    /// sent, and the cold sidecar spawn + `thread/start` handshake takes
    /// seconds — a pane-header rename committed inside that window
    /// targeted a record the server had accepted on the wire but not yet
    /// admitted (404 NAME_NOT_FOUND), silently losing the manual
    /// pre-durable name to the first-message fallback. Admission is
    /// idempotent, so the post-`thread/start` re-ensure in
    /// `admit_create_handle_named` answers the same record and adds the
    /// stash/acquisition evidence unchanged.
    #[tokio::test(flavor = "multi_thread")]
    async fn create_admits_the_pending_record_before_the_sidecar_answers_thread_start() {
        let _guard = ENV_LOCK.lock().await;
        configure_fake_codex_cmd(
            r#"{"threadStartThreadId":"thread-early-admit","delayMethodsMs":{"thread/start":1500}}"#,
        );
        let (st, _rx) = state_with_bus();
        let sink = crate::naming::test_support::RecordingSink::new();
        st.set_session_naming(sink.clone());
        let create = FreshAgentCreate {
            collaboration_mode: None,
            pane_id: None,
            observed_epoch: None,
            observed_generation: None,
            view_id: None,
            naming_handle: Some("handle-codex-early".to_string()),
            request_id: "req-codex-early".to_string(),
            session_type: freshell_protocol::SessionType::Freshcodex,
            provider: Some(freshell_protocol::AgentProvider::Codex),
            cwd: None,
            legacy_restore_context: None,
            resume_session_id: None,
            session_ref: None,
            model: None,
            model_selection: None,
            permission_mode: None,
            sandbox: None,
            effort: None,
            plugins: None,
            tab_id: None,
        };

        // Park the create inside its deferred `thread/start` handshake.
        let joined = tokio::spawn(async move { st.handle_create(create, None).await });
        // We are inside the window: the deferred answer is 1500ms out, and
        // the record — admitted at REQUEST RECEIPT — must already exist.
        tokio::time::sleep(std::time::Duration::from_millis(400)).await;
        use crate::naming::SessionNaming as _;
        let updates = sink
            .get(vec![
                freshell_protocol::session_names::SessionNameRef::Pending {
                    id: "handle-codex-early".to_string(),
                },
            ])
            .await
            .expect("get resolves");
        assert_eq!(
            updates.len(),
            1,
            "the pending record must exist before `thread/start` answers"
        );

        // Cleanup: let the deferred handshake finish so no spawned sidecar
        // outlives the test.
        let _ = joined.await;
        std::env::remove_var("CODEX_CMD");
        std::env::remove_var("FAKE_CODEX_APP_SERVER_BEHAVIOR");
    }

    // ── wedged-sidecar quiet deadman (the wedged-but-ALIVE sidecar case) ────────
    //
    // These tests drive the production paths (`handle_send` / `get_snapshot` /
    // the real notification consumer) against a scripted `ChannelPeer` whose child
    // stand-in is a live `sleep` process (the wedged-ALIVE shape: process up, zero
    // events, no exit). Window values are scaled via
    // `set_codex_quiet_window_ms_for_tests`; no `tokio::time::pause` (unused here).

    /// Build the WS client frame the existing tests feed to `handle_send`.
    fn send_msg(session_id: &str, text: &str) -> FreshAgentSend {
        FreshAgentSend {
            provider: freshell_protocol::AgentProvider::Codex,
            session_id: session_id.to_string(),
            session_type: freshell_protocol::SessionType::Freshcodex,
            text: text.to_string(),
            cwd: None,
            images: None,
            request_id: None,
            settings: None,
            observed_epoch: None,
            observed_generation: None,
            checkpoint_intent: None,
        }
    }

    #[tokio::test]
    async fn accepted_turn_without_started_still_reports_its_itemless_failure() {
        let _process_fixture = crate::session_lease::process_fixture::lock().await;
        for scenario in 0..3 {
            let completion_before_response = scenario != 1;
            let native_home = small_native_home("thread-accepted-error");
            let (state, mut events) = state_with_bus();
            let (transport, peer) = freshell_codex::new_channel_transport();
            let (client, notifs) = CodexAppServerClient::connect(transport);
            insert_fake_session_with_real_consumer(
                &state,
                "thread-accepted-error",
                Arc::new(client),
                Arc::new(StdMutex::new(None)),
                notifs,
                spawn_sleeper(),
                "codex-accepted-without-started",
            )
            .await;
            let projection = {
                let sessions = state.sessions.lock().await;
                sessions["thread-accepted-error"].projection.clone()
            };
            {
                let mut projection = projection.lock().unwrap();
                let fence = projection.begin_history_read();
                projection
                    .accept_native_history(
                        &json!({"thread":{"id":"thread-accepted-error","historyMode":"paginated",
                            "status":{"type":"idle"},"turns":[{"id":"old","status":"completed",
                            "itemsView":"full","items":[]}]}}),
                        &fence,
                    )
                    .unwrap();
            }
            let send = {
                let state = state.clone();
                tokio::spawn(async move {
                    state
                        .handle_send(send_msg("thread-accepted-error", "hello"))
                        .await
                })
            };
            answer_initialize_in_home(&peer, native_home.path()).await;
            let (request_id, method, _) = peer.expect_request().await;
            assert_eq!(method, "turn/start");
            if scenario == 2 {
                // The read began after dispatch but overtakes the response;
                // its terminal row is not evidence that this is an old turn.
                let mut projection = projection.lock().unwrap();
                let fence = projection.begin_history_read();
                projection
                    .accept_native_history(
                        &json!({"thread":{"id":"thread-accepted-error",
                            "historyMode":"paginated","status":{"type":"idle"},"turns":[
                            {"id":"old","status":"completed","itemsView":"full","items":[]},
                            {"id":"accepted","status":"completed","itemsView":"full","items":[
                                {"type":"userMessage","id":"saved-user","content":[{"type":"text","text":"saved prompt"}]},
                                {"type":"agentMessage","id":"saved-answer","text":"saved answer"}
                            ]}
                        ]}}),
                        &fence,
                    )
                    .unwrap();
            }
            let message = "Selected model is at capacity. Please try a different model.";
            let emit_completion = || {
                // Neither a completed old turn nor a foreign turn may claim
                // the accepted turn's error, even when their events arrive first.
                for id in ["old", "foreign"] {
                    peer.emit_notification(
                        "turn/completed",
                        json!({"threadId":"thread-accepted-error",
                        "turn":{"id":id,"status":"failed","error":{"message":"stale diagnostic"}}}),
                    );
                }
                if completion_before_response {
                    peer.emit_notification(
                        "error",
                        json!({"threadId":"thread-accepted-error",
                        "turnId":"accepted","willRetry":false,"error":{"message":message}}),
                    );
                }
                if scenario == 2 {
                    peer.emit_notification("item/started", json!({"threadId":"thread-accepted-error",
                        "turnId":"accepted","item":{"type":"agentMessage","id":"saved-answer","text":""}}));
                    peer.emit_notification(
                        "item/agentMessage/delta",
                        json!({"threadId":"thread-accepted-error",
                        "turnId":"accepted","itemId":"saved-answer","delta":"MUST_NOT_APPEND"}),
                    );
                }
                peer.emit_notification("turn/completed", json!({"threadId":"thread-accepted-error",
                    "turn":{"id":"accepted","status":"failed","items":[],
                    "error":if completion_before_response { Value::Null } else { json!({"message":message}) }}}));
            };
            if completion_before_response {
                emit_completion();
            }
            peer.respond(&request_id, json!({"turn":{"id":"accepted"}}));
            let accepted = send.await.unwrap();
            if !completion_before_response {
                emit_completion();
            }
            let collect = collect_frames_until(&mut events, Duration::from_secs(2), |frame| {
                frame["event"]["type"] == "freshAgent.transcript.patch"
                    && frame["event"]["ops"].to_string().contains(message)
            })
            .await;
            peer.disconnect();
            state.shutdown().await;
            assert!(
                matches!(accepted, CodexSendOutcome::Accepted { submitted_turn_id, .. } if submitted_turn_id == "accepted")
            );
            assert!(
                collect.matched,
                "the accepted turn must publish its provider error immediately: {:?}",
                collect.frames
            );
            assert!(
                !collect.frames.iter().any(|frame| frame["event"]["type"]
                    == "freshAgent.transcript.patch"
                    && frame["event"]["ops"]
                        .to_string()
                        .contains("stale diagnostic")),
                "unrelated completions must stay inert"
            );
            if scenario == 2 {
                let frames = json!(collect.frames).to_string();
                assert!(
                    frames.contains("saved prompt") && frames.contains("saved answer"),
                    "saved context and the failure must both survive: {frames}"
                );
                assert!(
                    !frames.contains("MUST_NOT_APPEND"),
                    "saved items cannot become append baselines"
                );
            }
        }
    }

    #[tokio::test]
    async fn ambiguous_send_preserves_unattributed_provider_failure_after_disconnect() {
        let _process_fixture = crate::session_lease::process_fixture::lock().await;
        let native_home = small_native_home("thread-ambiguous-error");
        let (state, mut events) = state_with_bus();
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, notifs) = CodexAppServerClient::connect(transport);
        insert_fake_session_with_real_consumer(
            &state,
            "thread-ambiguous-error",
            Arc::new(client),
            Arc::new(StdMutex::new(None)),
            notifs,
            spawn_sleeper(),
            "codex-ambiguous-error",
        )
        .await;
        let (projection, turn_state) = {
            let sessions = state.sessions.lock().await;
            let session = &sessions["thread-ambiguous-error"];
            (session.projection.clone(), session.turn_state.clone())
        };
        {
            let mut projection = projection.lock().unwrap();
            let fence = projection.begin_history_read();
            projection
                .accept_native_history(
                    &json!({"thread":{"id":"thread-ambiguous-error",
                        "historyMode":"paginated","status":{"type":"idle"},"turns":[
                        {"id":"old","status":"completed","itemsView":"full","items":[]}
                    ]}}),
                    &fence,
                )
                .unwrap();
        }
        let send = {
            let state = state.clone();
            tokio::spawn(async move {
                state
                    .handle_send(send_msg("thread-ambiguous-error", "hello"))
                    .await
            })
        };
        answer_initialize_in_home(&peer, native_home.path()).await;
        let (_request_id, method, _) = peer.expect_request().await;
        assert_eq!(method, "turn/start");
        peer.emit_notification(
            "turn/completed",
            json!({"threadId":"thread-ambiguous-error",
            "turn":{"id":"old","status":"failed","error":{"message":"stale diagnostic"}}}),
        );
        peer.emit_notification(
            "turn/completed",
            json!({"threadId":"foreign-thread",
            "turn":{"id":"foreign","status":"failed","error":{"message":"foreign diagnostic"}}}),
        );
        let message = "Selected model is at capacity. Please try a different model.";
        peer.emit_notification(
            "turn/completed",
            json!({"threadId":"thread-ambiguous-error",
            "turn":{"id":"unattributed","status":"failed","items":[],"error":{"message":message}}}),
        );
        peer.disconnect();
        let outcome = send.await.unwrap();
        let collect = collect_frames_until(&mut events, Duration::from_secs(2), |frame| {
            frame["event"]["type"] == "freshAgent.notice"
                && frame["event"]["code"] == "CODEX_UNATTRIBUTED_PROVIDER_ERROR"
                && frame["event"]["message"] == message
        })
        .await;
        let unknown_delivery = turn_state.lock().unwrap().has_unknown_delivery();
        let retained = state
            .retained_state("thread-ambiguous-error")
            .await
            .unwrap();
        state.shutdown().await;
        assert!(
            matches!(outcome, CodexSendOutcome::Ambiguous { .. }),
            "a lost RPC response must remain ambiguous"
        );
        assert!(
            unknown_delivery,
            "the uncorrelated diagnostic must not settle the dispatch"
        );
        assert!(
            collect.matched,
            "the exact provider diagnostic must be shown: {:?}",
            collect.frames
        );
        assert_eq!(
            retained["snapshot"]["extensions"]["codex"]["unattributedProviderError"], message,
            "a later attachment must recover the exact session diagnostic"
        );
        assert!(
            !collect.frames.iter().any(|frame| frame["event"]
                .to_string()
                .contains("stale diagnostic")
                || frame["event"].to_string().contains("foreign diagnostic")),
            "old and foreign completions must stay fenced"
        );
        assert!(
            !collect.frames.iter().any(|frame| frame["event"]["type"]
                == "freshAgent.transcript.patch"
                && frame["event"]["ops"].to_string().contains("unattributed")),
            "an ambiguous response must not assign the failure to this send"
        );
    }

    async fn check_active_provider_error_is_retained(final_status: &'static str) {
        let _process_fixture = crate::session_lease::process_fixture::lock().await;
        let thread_id = "thread-active-provider-error";
        let native_home = small_native_home(thread_id);
        let (state, mut events) = state_with_bus();
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, notifs) = CodexAppServerClient::connect(transport);
        insert_fake_session_with_real_consumer(
            &state,
            thread_id,
            Arc::new(client),
            Arc::new(StdMutex::new(None)),
            notifs,
            spawn_sleeper(),
            "codex-active-provider-error",
        )
        .await;
        let send = {
            let state = state.clone();
            tokio::spawn(async move { state.handle_send(send_msg(thread_id, "hello")).await })
        };
        answer_initialize_in_home(&peer, native_home.path()).await;
        let (request_id, method, _) = peer.expect_request().await;
        assert_eq!(method, "turn/start");
        peer.respond(&request_id, json!({"turn":{"id":"accepted"}}));
        let accepted = send.await.unwrap();
        peer.emit_notification(
            "error",
            json!({"threadId":thread_id,"turnId":"accepted",
            "willRetry":true,"error":{"message":"temporary retry"}}),
        );
        peer.emit_notification(
            "error",
            json!({"threadId":"foreign-thread","turnId":"accepted",
            "willRetry":false,"error":{"message":"foreign warning"}}),
        );
        peer.emit_notification(
            "error",
            json!({"threadId":thread_id,"turnId":"old",
            "willRetry":false,"error":{"message":"stale warning"}}),
        );
        let prior = collect_frames_until(&mut events, Duration::from_secs(2), |frame| {
            frame["event"]["code"] == "CODEX_PROVIDER_ERROR"
                && frame["event"]["message"] == "stale warning"
        })
        .await;
        let before = state.retained_state(thread_id).await.unwrap();
        let message = "Selected model is at capacity. Please try a different model.";
        peer.emit_notification(
            "error",
            json!({"threadId":thread_id,"turnId":"accepted",
            "willRetry":false,"error":{"message":message}}),
        );
        let warning = collect_frames_until(&mut events, Duration::from_secs(2), |frame| {
            frame["event"]["code"] == "CODEX_PENDING_PROVIDER_ERROR"
        })
        .await;
        let retained = state.retained_state(thread_id).await.unwrap();
        let snapshot_task = {
            let state = state.clone();
            tokio::spawn(async move { state.get_snapshot(thread_id, None).await })
        };
        let (read_id, read_method, _) = peer.expect_request().await;
        assert_eq!(read_method, "thread/read");
        peer.respond(
            &read_id,
            json!({"thread":{"id":thread_id,"historyMode":"paginated",
            "status":{"type":"active"},"turns":[]}}),
        );
        let snapshot = snapshot_task.await.unwrap().unwrap();
        if final_status == "closed" {
            peer.emit_notification("thread/closed", json!({"threadId":thread_id}));
        } else {
            peer.emit_notification(
                "turn/completed",
                json!({"threadId":thread_id,
                "turn":{"id":"accepted","status":final_status,"error":null}}),
            );
        }
        let cleared = collect_frames_until(&mut events, Duration::from_secs(2), |frame| {
            frame["event"]["code"] == "CODEX_PENDING_PROVIDER_ERROR_CLEARED"
        })
        .await;
        let after = state.retained_state(thread_id).await.unwrap();
        peer.disconnect();
        state.shutdown().await;
        assert!(
            matches!(accepted, CodexSendOutcome::Accepted { submitted_turn_id, .. } if submitted_turn_id == "accepted")
        );
        assert!(
            prior.matched
                && before["snapshot"]["extensions"]["codex"]["pendingProviderError"].is_null(),
            "retry, foreign and old-turn errors must not become provisional failures"
        );
        assert!(
            warning.matched,
            "the active provider error needs a retained notice: {:?}",
            warning.frames
        );
        assert_eq!(
            warning.frames.last().unwrap()["event"]["turnId"],
            "accepted"
        );
        assert_eq!(warning.frames.last().unwrap()["event"]["message"], message);
        assert!(
            !warning
                .frames
                .iter()
                .any(|frame| frame["event"]["code"] == "CODEX_PROVIDER_ERROR"
                    && frame["event"]["message"] == message),
            "the same error must not appear twice"
        );
        for value in [&retained["snapshot"], &snapshot] {
            assert_eq!(
                value["extensions"]["codex"]["pendingProviderError"],
                json!({"turnId":"accepted","message":message})
            );
            assert_eq!(
                value["status"], "running",
                "a provisional diagnostic is not a failed turn"
            );
        }
        assert!(
            cleared.matched,
            "completion must clear the provisional notice: {:?}",
            cleared.frames
        );
        assert_eq!(
            cleared.frames.last().unwrap()["event"]["turnId"],
            "accepted"
        );
        assert_eq!(
            cleared.frames.last().unwrap()["event"]["outcome"],
            if matches!(final_status, "failed" | "closed") {
                "failed"
            } else {
                "other"
            }
        );
        assert!(after["snapshot"]["extensions"]["codex"]["pendingProviderError"].is_null());
        if matches!(final_status, "failed" | "closed") {
            assert!(
                cleared.frames.iter().any(|frame| frame["event"]["type"]
                    == "freshAgent.transcript.patch"
                    && frame["event"]["ops"].to_string().contains(message)),
                "a failed completion must publish the actual error row before clearing"
            );
        }
    }

