    #[test]
    fn build_codex_turn_json_turn_id_semantics_single_row_keeps_raw_id_multi_row_disambiguates() {
        // Pinning the documented turnId scheme (see the doc comment on `build_codex_turn_json`):
        // the reference's HMAC-derived turnId (`createCodexDisplayId`, `normalize.ts:574-593`)
        // requires a per-server-instance secret this crate does not own (`configStore` in
        // `server/index.ts:322-326`). This port's non-cryptographic, deterministic substitute:
        // a raw turn producing exactly one display row keeps `turnId == raw turn id` (PR-5
        // precedent, unchanged for the common case); a raw turn that SPLITS into multiple rows
        // disambiguates each extra row as `"{raw_turn_id}:row-{index}"`.
        let single_row_turn = json!({
            "id": "turn-single-id",
            "items": [{ "type": "agentMessage", "id": "a-1", "text": "hi" }],
        });
        let turns = build_codex_turn_json(&single_row_turn, 0).expect("turn builds");
        assert_eq!(turns.len(), 1);
        assert_eq!(turns[0]["id"], json!("turn-single-id"));
        assert_eq!(turns[0]["turnId"], json!("turn-single-id"));

        let multi_row_turn = json!({
            "id": "turn-multi-id",
            "items": [
                { "type": "userMessage", "id": "u-1", "content": [{ "type": "text", "text": "hi" }] },
                { "type": "agentMessage", "id": "a-1", "text": "hello" },
            ],
        });
        let turns = build_codex_turn_json(&multi_row_turn, 0).expect("turn builds");
        assert_eq!(turns.len(), 2);
        assert_eq!(turns[0]["id"], json!("turn-multi-id:row-0"));
        assert_eq!(turns[0]["turnId"], json!("turn-multi-id:row-0"));
        assert_eq!(turns[1]["id"], json!("turn-multi-id:row-1"));
        assert_eq!(turns[1]["turnId"], json!("turn-multi-id:row-1"));
    }

    #[test]
    fn checkpoint_turn_identity_codex_binds_native_id_only_to_one_actual_user_row() {
        let raw_turn = json!({
            "id": "turn-native-1",
            "status": "completed",
            "items": [
                { "id": "user-item-1", "type": "userMessage", "content": [{ "type": "text", "text": "same prompt" }] },
                { "id": "assistant-item-1", "type": "agentMessage", "text": "answer" }
            ]
        });

        let turns = build_codex_turn_json(&raw_turn, 0).expect("turn builds");
        let user_rows: Vec<_> = turns.iter().filter(|turn| turn["role"] == "user").collect();
        assert_eq!(user_rows.len(), 1);
        assert_eq!(user_rows[0]["id"], "turn-native-1:row-0");
        assert_eq!(user_rows[0]["turnId"], "turn-native-1:row-0");
        assert_eq!(user_rows[0]["nativeTurnId"], "turn-native-1");
        assert!(turns
            .iter()
            .filter(|turn| turn["role"] != "user")
            .all(|turn| turn.get("nativeTurnId").is_none()));
        let raw_thread = json!({"thread":{"turns":[raw_turn.clone()]}});
        assert_eq!(
            checkpoint_codex_turn_identity(&raw_thread, "turn-native-1"),
            Some((
                "turn-native-1".to_string(),
                "turn-native-1:row-0".to_string()
            )),
            "the receipt identity comes from the unique provider-persisted user row"
        );
        assert_eq!(
            checkpoint_codex_turn_identity(&raw_thread, "some-other-turn"),
            None,
            "a snapshot row from another send cannot satisfy this request"
        );
        let mut in_progress_turn = raw_turn.clone();
        in_progress_turn["status"] = json!("inProgress");
        assert_eq!(
            checkpoint_codex_turn_identity(
                &json!({"thread":{"turns":[in_progress_turn]}}),
                "turn-native-1"
            ),
            None,
            "an in-progress turn's row id can still change when Codex adds its assistant row"
        );

        let ambiguous = json!({
            "id": "turn-native-ambiguous",
            "status": "completed",
            "items": [
                { "id": "u1", "type": "userMessage", "content": [{ "type": "text", "text": "same prompt" }] },
                { "id": "a1", "type": "agentMessage", "text": "answer" },
                { "id": "u2", "type": "userMessage", "content": [{ "type": "text", "text": "same prompt" }] }
            ]
        });
        let turns = build_codex_turn_json(&ambiguous, 0).expect("ambiguous turn still builds");
        assert_eq!(
            turns.iter().filter(|turn| turn["role"] == "user").count(),
            2
        );
        assert!(turns.iter().all(|turn| turn.get("nativeTurnId").is_none()));
        assert_eq!(
            checkpoint_codex_turn_identity(
                &json!({"thread":{"turns":[ambiguous]}}),
                "turn-native-ambiguous"
            ),
            None,
            "an ambiguous multi-user provider turn cannot emit a native identity receipt"
        );
    }

    #[tokio::test]
    async fn checkpoint_identity_probe_retries_until_delayed_user_row_is_persisted() {
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, _notifs) = CodexAppServerClient::connect(transport);
        let (state, mut rx) = state_with_bus();
        let active_turn = Arc::new(StdMutex::new(Some("turn-persisted-user".to_string())));
        drop(
            state.spawn_checkpoint_identity_probe(CodexCheckpointIdentityProbe {
                client: Arc::new(client),
                session_id: "thread-checkpoint-receipt".to_string(),
                submitted_turn_id: "turn-persisted-user".to_string(),
                request_id: "request-checkpoint-1".to_string(),
                logical_attempt_id: "logical-checkpoint-1".to_string(),
                active_turn: active_turn.clone(),
                exited: Arc::new(AtomicBool::new(false)),
                cancelled: Arc::new(AtomicBool::new(false)),
            }),
        );

        assert!(
            tokio::time::timeout(Duration::from_millis(50), peer.expect_request())
                .await
                .is_err(),
            "identity reads wait until the accepted turn has retired"
        );
        *active_turn.lock().expect("active turn mutex") = None;

        let (initialize_id, initialize_method, _) = peer.expect_request().await;
        assert_eq!(initialize_method, "initialize");
        peer.respond(
            &initialize_id,
            json!({ "userAgent": "test", "codexHome": "/h", "platformFamily": "u", "platformOs": "l" }),
        );
        let _ = peer.expect_notification().await;
        for attempt in 1..=12 {
            let (read_id, read_method, read_params) =
                tokio::time::timeout(Duration::from_secs(2), peer.expect_request())
                    .await
                    .expect("probe should continue while the user row is not persisted");
            assert_eq!(read_method, "thread/read", "attempt {attempt}");
            assert_eq!(read_params["threadId"], "thread-checkpoint-receipt");
            assert_eq!(read_params["includeTurns"], true);
            peer.respond(
                &read_id,
                json!({
                    "thread": {
                        "id": "thread-checkpoint-receipt",
                        "status": "running",
                        "turns": []
                    }
                }),
            );
        }

        let (persisted_read_id, persisted_read_method, persisted_read_params) =
            tokio::time::timeout(Duration::from_secs(2), peer.expect_request())
                .await
                .expect("probe should continue after twelve empty history reads");
        assert_eq!(persisted_read_method, "thread/read");
        assert_eq!(
            persisted_read_params["threadId"],
            "thread-checkpoint-receipt"
        );
        assert_eq!(persisted_read_params["includeTurns"], true);
        peer.respond(
            &persisted_read_id,
            json!({
                "thread": {
                    "id": "thread-checkpoint-receipt",
                    "status": "idle",
                    "turns": [{
                        "id": "turn-persisted-user",
                        "status": "completed",
                        "items": [
                            { "id": "user-row", "type": "userMessage", "content": [
                                { "type": "text", "text": "prompt is not copied into receipt" }
                            ] },
                            { "id": "assistant-row", "type": "agentMessage", "text": "answer" }
                        ]
                    }]
                }
            }),
        );

        let frame = tokio::time::timeout(Duration::from_secs(1), rx.recv())
            .await
            .expect("provider identity receipt was broadcast")
            .expect("broadcast bus remains open");
        let frame: Value = serde_json::from_str(&frame).expect("receipt is JSON");
        assert_eq!(frame["type"], "freshAgent.event");
        assert_eq!(frame["provider"], "codex");
        assert_eq!(frame["sessionId"], "thread-checkpoint-receipt");
        assert_eq!(frame["event"]["type"], "checkpointTurnIdentity");
        assert_eq!(frame["event"]["requestId"], "request-checkpoint-1");
        assert_eq!(frame["event"]["logicalAttemptId"], "logical-checkpoint-1");
        assert_eq!(frame["event"]["nativeTurnId"], "turn-persisted-user");
        assert_eq!(frame["event"]["displayTurnId"], "turn-persisted-user:row-0");
        assert!(
            frame["event"].get("text").is_none(),
            "checkpoint identity receipts never carry prompt text"
        );
    }

    #[tokio::test]
    async fn checkpoint_identity_probe_retries_after_a_thread_read_error() {
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, _notifs) = CodexAppServerClient::connect(transport);
        let (state, mut rx) = state_with_bus();
        drop(
            state.spawn_checkpoint_identity_probe(CodexCheckpointIdentityProbe {
                client: Arc::new(client),
                session_id: "thread-checkpoint-read-retry".to_string(),
                submitted_turn_id: "turn-persisted-after-retry".to_string(),
                request_id: "request-checkpoint-retry".to_string(),
                logical_attempt_id: "logical-checkpoint-retry".to_string(),
                active_turn: Arc::new(StdMutex::new(None)),
                exited: Arc::new(AtomicBool::new(false)),
                cancelled: Arc::new(AtomicBool::new(false)),
            }),
        );

        let (initialize_id, initialize_method, _) = peer.expect_request().await;
        assert_eq!(initialize_method, "initialize");
        peer.respond(
            &initialize_id,
            json!({ "userAgent": "test", "codexHome": "/h", "platformFamily": "u", "platformOs": "l" }),
        );
        let _ = peer.expect_notification().await;
        let (first_read_id, first_read_method, _) = peer.expect_request().await;
        assert_eq!(first_read_method, "thread/read");
        peer.respond_error(&first_read_id, -32000, "temporary history read failure");

        let (second_read_id, second_read_method, _) = peer.expect_request().await;
        assert_eq!(second_read_method, "thread/read");
        peer.respond(
            &second_read_id,
            json!({
                "thread": {
                    "id": "thread-checkpoint-read-retry",
                    "status": "idle",
                    "turns": [{
                        "id": "turn-persisted-after-retry",
                        "status": "completed",
                        "items": [
                            { "id": "user-row", "type": "userMessage", "content": [
                                { "type": "text", "text": "prompt is excluded" }
                            ] },
                            { "id": "assistant-row", "type": "agentMessage", "text": "answer" }
                        ]
                    }]
                }
            }),
        );

        let frame = tokio::time::timeout(Duration::from_secs(1), rx.recv())
            .await
            .expect("retry emitted the provider identity receipt")
            .expect("broadcast bus remains open");
        let frame: Value = serde_json::from_str(&frame).expect("receipt is JSON");
        assert_eq!(frame["event"]["type"], "checkpointTurnIdentity");
        assert_eq!(frame["event"]["requestId"], "request-checkpoint-retry");
        assert_eq!(
            frame["event"]["logicalAttemptId"],
            "logical-checkpoint-retry"
        );
        assert_eq!(frame["event"]["nativeTurnId"], "turn-persisted-after-retry");
    }

    #[tokio::test]
    async fn checkpoint_identity_probe_stops_when_its_session_is_killed_mid_turn() {
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, _notifs) = CodexAppServerClient::connect(transport);
        let client = Arc::new(client);
        let (state, _rx) = state_with_bus();
        let active_turn = Arc::new(StdMutex::new(Some("turn-stopped".to_string())));
        insert_fake_session(
            &state,
            "thread-stopped-checkpoint",
            client.clone(),
            active_turn.clone(),
            spawn_sleeper(),
            "codex-sidecar-checkpoint-stop",
        )
        .await;
        let (cancelled, exited) = {
            let sessions = state.sessions.lock().await;
            let session = sessions
                .get("thread-stopped-checkpoint")
                .expect("fixture session inserted");
            (
                session.checkpoint_probe_cancelled.clone(),
                session.exited.clone(),
            )
        };
        let mut probe = state.spawn_checkpoint_identity_probe(CodexCheckpointIdentityProbe {
            client,
            session_id: "thread-stopped-checkpoint".to_string(),
            submitted_turn_id: "turn-stopped".to_string(),
            request_id: "request-stopped".to_string(),
            logical_attempt_id: "logical-stopped".to_string(),
            active_turn,
            exited,
            cancelled: cancelled.clone(),
        });

        assert!(
            tokio::time::timeout(Duration::from_millis(50), peer.expect_request())
                .await
                .is_err(),
            "the probe should wait for the in-flight turn before reading history"
        );
        // Closing the client drains its reader task; dropping the fake provider lets its
        // receive future finish so the fixture's transport close can complete.
        drop(peer);

        state
            .handle_kill(FreshAgentKill {
                observed_epoch: None,
                observed_generation: None,
                provider: freshell_protocol::AgentProvider::Codex,
                session_id: "thread-stopped-checkpoint".to_string(),
                session_type: freshell_protocol::SessionType::Freshcodex,
                cwd: None,
            })
            .await;

        let probe_stopped = tokio::time::timeout(Duration::from_secs(1), &mut probe)
            .await
            .is_ok();
        if !probe_stopped {
            // Keep this regression leak-free while it is red: the pre-fix kill path
            // leaves the probe polling, so explicitly release it after the assertion
            // window and then verify that it settles.
            cancelled.store(true, Ordering::SeqCst);
            tokio::time::timeout(Duration::from_secs(1), &mut probe)
                .await
                .expect("test cleanup releases the probe")
                .expect("probe task joins");
        }
        assert!(
            probe_stopped,
            "killing a session must cancel its checkpoint probe instead of retaining it forever"
        );
    }

    #[test]
    fn build_codex_turn_json_empty_response_synthetic_row_also_carries_assistant_role() {
        // A completed turn with ONLY user-role items and no assistant output gets a synthetic
        // "empty-response" row appended (`normalize.ts:642-652`) -- also role `assistant`,
        // matching `createSyntheticPendingRow`'s hardcoded role.
        let raw_turn = json!({
            "id": "turn-empty-response",
            "status": "completed",
            "items": [
                { "type": "userMessage", "id": "u-1", "content": [{ "type": "text", "text": "hi" }] },
            ],
        });
        let turns = build_codex_turn_json(&raw_turn, 0).expect("turn builds");
        assert_eq!(
            turns.len(),
            2,
            "user row + synthetic empty-response row: {turns:?}"
        );
        assert_eq!(turns[0]["role"], json!("user"));
        assert_eq!(turns[1]["role"], json!("assistant"));
        assert_eq!(
            turns[1]["items"][0]["text"],
            json!("Codex completed this turn without recording an assistant response.")
        );
    }

    // ── kata 1wxv Task 5: snapshot rollback surfacing (codex) ─────────────────
    //
    // The capability stamp is SESSION-SCOPED by the DURABLE history mode
    // (correction item 1, r3): `undo` ⟺ `Some(Paginated)`; legacy AND unknown
    // (`None` — a missing/unparseable durable mode) stamp `undo:false`. `redo`
    // is permanently false (codex revert is destructive; there is no redo
    // primitive). The marker bucket comes from the LEDGER record (the r3
    // entries union) — `thread/revert` destroys the tail, so there is no
    // provider-side projection to recompute marker content from.

    fn codex_raw_thread_updated_at_7() -> Value {
        json!({
            "thread": {
                "id": "thread-9",
                "preview": "",
                "updatedAt": 7,
                "status": { "type": "idle" },
                "turns": [{
                    "id": "turn-1",
                    "status": "completed",
                    "items": [{
                        "type": "userMessage",
                        "id": "u-1",
                        "content": [{ "type": "text", "text": "earlier" }],
                    }],
                }],
            }
        })
    }

    /// One ledger record whose entries union is a single op over the USER-role
    /// display turn `turn-9` (last op at ms 100 — the revision floor).
    fn codex_rollback_record_with_turn_9() -> crate::rollback_record::RollbackRecord {
        use crate::rollback_record::*;
        let mut record = RollbackRecord::empty(50);
        record.push_entry(
            RollbackEntry {
                removed_turns: vec![json!({
                    "id": "turn-9",
                    "turnId": "turn-9",
                    "ordinal": 1,
                    "source": "durable",
                    "role": "user",
                    "summary": "later",
                    "items": [{ "id": "turn-9:item-0", "kind": "text", "text": "later" }],
                })],
                prompt_text: "later".into(),
                at_ms: 90,
                epoch: 0,
            },
            100,
        );
        record
    }

    #[test]
    fn codex_snapshot_stamps_paginated_capabilities_the_marker_bucket_and_the_revision_floor() {
        let record = codex_rollback_record_with_turn_9();
        let snap = build_codex_snapshot_json(
            "thread-9",
            &codex_raw_thread_updated_at_7(),
            false,
            Some(HistoryMode::Paginated),
            Some(&record),
            false,
        )
        .expect("snapshot builds");
        assert_eq!(snap["capabilities"]["undo"], json!(true));
        assert_eq!(snap["capabilities"]["redo"], json!(false));
        assert_eq!(
            snap["rollback"],
            json!({ "canRedo": false, "undoneDepth": 1, "redoableTurnIds": [] }),
            "undoneDepth is the USER-role step count of the bucket (never entries.len()); F6: codex is undo-only ⇒ NO marker is ever redoable"
        );
        let bucket = snap["rolledBackTurns"].as_array().expect("bucket");
        assert_eq!(bucket.len(), 1);
        assert_eq!(bucket[0]["rolledBack"], json!(true));
        assert_eq!(
            bucket[0]["restorable"],
            json!(false),
            "codex is undo-only — its markers are collapsed-from-birth (never restorable)"
        );
        assert_eq!(bucket[0]["turnId"], json!("turn-9"));
        assert_eq!(
            snap["revision"],
            json!(100),
            "the record's lastOpAtMs is the revision floor (basis 7 loses)"
        );
    }

    #[test]
    fn fresh_agent_operation_matrix_parity_codex() {
        let snapshot = build_codex_snapshot_json(
            "native",
            &codex_raw_thread_updated_at_7(),
            false,
            Some(HistoryMode::Paginated),
            None,
            false,
        )
        .unwrap();
        assert_eq!(snapshot["capabilities"]["send"], true);
        assert_eq!(snapshot["capabilities"]["fork"], true);
        assert_eq!(snapshot["capabilities"]["undo"], true);
        assert_eq!(snapshot["capabilities"]["redo"], false);
    }

    #[test]
    fn codex_snapshot_stamps_legacy_and_unknown_history_undo_false() {
        // `None` == a legacy thread OR an unparseable durable mode — the stamp is
        // session-scoped and NEVER hard-coded true.
        let record = codex_rollback_record_with_turn_9();
        let snap = build_codex_snapshot_json(
            "thread-9",
            &codex_raw_thread_updated_at_7(),
            false,
            None,
            Some(&record),
            false,
        )
        .expect("snapshot builds");
        assert_eq!(snap["capabilities"]["undo"], json!(false));
        assert_eq!(snap["capabilities"]["redo"], json!(false));
        // A record's markers still surface (the capability gate is client-side).
        assert_eq!(snap["rolledBackTurns"].as_array().expect("bucket").len(), 1);
    }

    #[test]
    fn codex_snapshot_without_a_record_hides_the_rollback_keys() {
        let snap = build_codex_snapshot_json(
            "thread-9",
            &codex_raw_thread_updated_at_7(),
            false,
            Some(HistoryMode::Paginated),
            None,
            false,
        )
        .expect("snapshot builds");
        assert!(
            snap.get("rolledBackTurns").is_none(),
            "the marker bucket is omitted entirely when nothing was rolled back"
        );
        assert!(snap.get("rollback").is_none());
        assert_eq!(snap["revision"], json!(7), "no floor without a record");
        assert_eq!(snap["capabilities"]["undo"], json!(true));
        assert_eq!(snap["capabilities"]["redo"], json!(false));
    }

    #[tokio::test]
    async fn get_snapshot_surfaces_the_durable_rollback_record_and_floors_the_revision() {
        let native_home = small_native_home("thread-1");
        let (transport, peer) = freshell_codex::new_channel_transport();
        let (client, _notifs) = CodexAppServerClient::connect(transport);
        let client = Arc::new(client);

        let (st, _rx, fake) = state_with_sink();
        insert_fake_session(
            &st,
            "thread-1",
            client,
            Arc::new(StdMutex::new(None)),
            spawn_sleeper(),
            "codex-sidecar-test-snapshot-rollback",
        )
        .await;
        fake.record_rollback("codex", "thread-1", codex_rollback_record_with_turn_9())
            .await
            .expect("record write");

        let driver = {
            let st = st.clone();
            tokio::spawn(async move { st.get_snapshot("thread-1", None).await })
        };
        let (init_id, _m, _p) = peer.expect_request().await;
        peer.respond(
            &init_id,
            json!({ "userAgent": "x", "codexHome": native_home.path(), "platformFamily": "u", "platformOs": "l" }),
        );
        let _ = peer.expect_notification().await;
        let (id, method, _params) = peer.expect_request().await;
        assert_eq!(method, "thread/read");
        // A STALE provider basis (3) — the rollback op (ms 100) is newer.
        peer.respond(
            &id,
            json!({ "thread": { "id": "thread-1", "status": { "type": "idle" }, "updatedAt": 3, "turns": [] } }),
        );

        let snapshot = driver.await.unwrap().expect("snapshot builds");
        assert_eq!(
            snapshot["capabilities"]["undo"],
            json!(true),
            "the paginated fixture session stamps undo (session-scoped, from the durable history mode record)"
        );
        assert_eq!(snapshot["capabilities"]["redo"], json!(false));
        assert_eq!(
            snapshot["rollback"],
            json!({ "canRedo": false, "undoneDepth": 1, "redoableTurnIds": [] })
        );
        assert_eq!(snapshot["rolledBackTurns"][0]["turnId"], json!("turn-9"));
        assert_eq!(snapshot["rolledBackTurns"][0]["rolledBack"], json!(true));
        assert_eq!(
            snapshot["rolledBackTurns"][0]["restorable"],
            json!(false),
            "codex is undo-only — never restorable over the live route either"
        );
        assert_eq!(
            snapshot["revision"],
            json!(100),
            "a stale provider basis never beats the record floor (the client monotonic watermark holds)"
        );
    }

